    FEATURE_ASSETS_V1,
    FEATURE_CRON_V1,
    FEATURE_D1_V1,
    FEATURE_KV_V1,
    FEATURE_QUEUES_V1,
    FEATURE_SQLITE_VEC_V1,
    FEATURE_R2_V1,
    FEATURE_WASM_V1,
    FEATURE_WORKFLOWS_V1,
];

