        (HEADER_BODY_SHA256, body_hash),
        (HEADER_SIGNATURE, signature),
    ] {
        headers.insert(
            axum::http::HeaderName::from_static(name),
            axum::http::HeaderValue::from_str(&value)
                .with_context(|| format!("encode peer header {name}"))?,
        );
    }
    Ok(headers)
}

